import React, { useState, useContext } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { OrderContext } from "./OrderContext";
import backgroundImage from "../Img/order8.jpg";

const AddOrder = () => {
  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  const [errors, setErrors] = useState({});
  const { setOrdersChanged } = useContext(OrderContext);
  const navigate = useNavigate();

  // ... (rest of the component logic remains unchanged)

  return (
    <div className="flex justify-center items-center min-h-[130vh] bg-[#f0f0f0] bg-cover bg-no-repeat bg-blend-multiply" style={{ backgroundImage: `url(${backgroundImage})` }}>
      <div className="bg-white bg-opacity-70 p-5 rounded-lg shadow-md w-full max-w-[700px] box-border">
        <h1 className="text-[#8B0000] font-bold text-center mb-5">
          Add Order
        </h1>
        <form onSubmit={sendData} className="w-full">
          {[ 
            { name: "firstName", type: "text", label: "First Name" },
            { name: "lastName", type: "text", label: "Last Name" },
            { name: "email", type: "email", label: "Email" },
            { name: "phoneNumber", type: "text", label: "Phone Number" },
            { name: "address", type: "text", label: "Address" },
            { name: "city", type: "text", label: "City" },
            { name: "orderId", type: "text", label: "Order ID" },
            { name: "specialInstructions", type: "text", label: "Special Instructions" },
            { name: "pickupTime", type: "datetime-local", label: "Pickup Time" },
            { name: "orderStatus", type: "text", label: "Order Status" },
          ].map((field) => (
            <div key={field.name} className="mb-4">
              <label htmlFor={field.name} className="block font-bold">
                {field.label}
              </label>
              <input
                type={field.type}
                id={field.name}
                name={field.name}
                className="w-full p-2.5 border border-gray-300 rounded-md box-border"
                placeholder={`Enter ${field.label}`}
                value={orderData[field.name]}
                onChange={handleChange}
              />
              {errors[field.name] && <p className="text-red-500 text-sm">{errors[field.name]}</p>}
            </div>
          ))}
          <button
            type="submit"
            className="bg-[#b30000] text-white py-2.5 px-5 border-none rounded-md cursor-pointer text-base mb-2.5"
          >
            Submit
          </button>
        </form>
        <div className="flex justify-center">
          <button
            onClick={handleBackToHome}
            className="bg-[#b30000] text-white py-2.5 px-5 border-none rounded-md cursor-pointer text-base w-[30%] mt-2.5"
          >
            Back to Home
          </button>
        </div>
      </div>
    </div>
  );
};

export default AddOrder;
